class RecoverySdk(AsyncSdk): def __init__(self): super().__init__() self.recovery_calls = 0 self.documented_recovery_calls = 0 self.recovery_events = [] self.execution_configurations = []
def configure_execution(self, config): self.execution_configurations.append(dict(config))
def recover_reservation_only_cancel_unknowns(self): self.recovery_calls += 1 self.recovery_events.append("reservation") return {"completed": True, "recovered_client_order_ids": []}
def recover_historical_documented_definite_rejections(self): self.documented_recovery_calls += 1 self.recovery_events.append("documented_rejection") return {"completed": True, "recovered_client_order_ids": []}
api = RecoverySdk() store = make_store(api) call_order = [] start_worker = store._start_command_worker
def checked_worker_start(): call_order.append("worker") assert api.recovery_calls == 1 assert api.documented_recovery_calls == 1 assert api.recovery_events == ["reservation", "documented_rejection"] start_worker()
monkeypatch.setattr(store, "_start_command_worker", checked_worker_start) try: > store.start()
